<div class="container-fluid py-4"><h2>Mis garantías</h2><p class="text-muted">Consulta la cobertura de los productos que has comprado.</p><?php if (!empty($garantias)): ?><div class="table-responsive bg-white rounded shadow-sm"><table class="table align-middle mb-0"><thead><tr><th>Garantía</th><th>Producto</th><th>Compra</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($garantias as $garantia): ?><tr><td>#<?= (int)$garantia->id_garantia ?></td><td><?= html_escape($garantia->nombre_producto) ?></td><td><?= !empty($garantia->fecha_venta) ? date('d/m/Y',strtotime($garantia->fecha_venta)) : '—' ?></td><td><span class="badge bg-info text-dark"><?= html_escape($garantia->estado_garantia) ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('cliente/garantias/detalle/'.$garantia->id_garantia) ?>">Ver detalle</a></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><div class="alert alert-info">No tienes garantías registradas.</div><?php endif ?></div>
